const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const os = require('node:os');
const path = require('node:path');
const {execFileSync} = require('node:child_process');
const root = path.resolve(__dirname, '..');
const html = fs.readFileSync(path.join(root, 'loomx/ui/index.htm'), 'utf8');

function context() {
  const requests = [];
  const ctx = {S:{bri:128,outs:Array.from({length:8},(_,i)=>({len:30,pin:i,type:'RGB',order:'GRB',bri:255,briLock:false}))},
    MOCK:false,Math,Number,Array,rememberSettingsPin:()=>{},clamp:(v,a,b)=>Math.min(b,Math.max(a,v)),
    typeOf:()=>({id:22,w:0}),encodeColorOrder:()=>0,
    req:async (url,body)=>{requests.push({url,body});return {}}};
  vm.createContext(ctx);
  vm.runInContext(html.slice(html.indexOf('var api={'),html.indexOf('function busesFrom')),ctx);
  vm.runInContext(html.slice(html.indexOf('function outputLevel('),html.indexOf('// Locked edits')),ctx);
  return {ctx,requests};
}

test('each output can change alone, including zero, with an explicit PIN',async()=>{
  for(let index=0;index<8;index++) for(const value of [0,128,255]){
    const {ctx,requests}=context();
    await ctx.api.setOutputLevels([{id:index,bri:value,lock:true}],'9876');
    assert.equal(requests[0].body.pin,'9876');
    assert.deepEqual(requests[0].body.hw.led.outputBri,[{id:index,bri:value,lock:true}]);
    assert.equal(requests[1].url,'/json/state');
  }
});
test('full output writes preserve brightness and locks',async()=>{
  const {ctx,requests}=context();
  ctx.S.outs[0].bri=0;ctx.S.outs[0].briLock=true;
  ctx.S.outs[7].bri=128;
  await ctx.api.writeBuses();
  const ins=requests[0].body.hw.led.ins;
  assert.equal(ins[0].bri,0);assert.equal(ins[0].briLock,true);
  assert.equal(ins[7].bri,128);assert.equal(ins[7].briLock,false);
  assert.equal(ins[1].bri,255);
});
test('state refresh restores levels and locks without losing blackout',()=>{
  const {ctx}=context();
  ctx.syncOutputLevels({outputBri:[{bri:0,lock:true},{bri:128,lock:false}]});
  assert.equal(ctx.S.outs[0].bri,0);assert.equal(ctx.S.outs[0].briLock,true);
  assert.equal(ctx.S.outs[1].bri,128);
});
test('driver locks capture effective brightness and ignore every master level',()=>{
  // Exercise the actual inline Bus methods with a minimal driver sink, independent of Arduino.
  const header=fs.readFileSync(path.join(root,'wled00/bus_manager.h'),'utf8');
  const methods=header.slice(header.indexOf('    void setOutputBrightness'),header.indexOf('    // AI: end'));
  const directory=fs.mkdtempSync(path.join(os.tmpdir(),'loomx-brightness-'));
  try{
    const file=path.join(directory,'test.cpp');
    fs.writeFileSync(file,`#include <cstdint>\n#include <cassert>\nclass Bus { public:
      uint8_t _bri=255,_outputBrightness=255,_masterBrightness=255; bool _brightnessLocked=false,_outputPower=true;
      void setBrightness(uint8_t value){_bri=value;}\n${methods}\n};
      int main(){
        Bus first, other;
        first.setMasterBrightness(128); first.setOutputBrightness(128);
        assert(first._bri==64); assert(other._bri==255);
        first.setBrightnessLocked(true); assert(first.getOutputBrightness()==64);
        for(unsigned value=0;value<256;value++){first.setMasterBrightness(value);assert(first._bri==64);}
        first.setOutputPower(false);assert(first._bri==0);first.setOutputPower(true);assert(first._bri==64);
        first.setOutputBrightness(0); assert(first._bri==0);
        first.setOutputBrightness(255); assert(first._bri==255);
        first.setBrightnessLocked(false); first.setMasterBrightness(0);assert(first._bri==0);
        first.setMasterBrightness(255);assert(first._bri==255);
        Bus restored; restored.setBrightnessLocked(true);restored.setOutputBrightness(73);
        restored.setMasterBrightness(0);assert(restored._bri==73);
      }`);
    execFileSync('c++',['-std=c++11','-Wall','-Wextra','-Werror',file,'-o',path.join(directory,'test')]);
    execFileSync(path.join(directory,'test'));
  }finally{fs.rmSync(directory,{recursive:true,force:true})}
});
// AI: end

