function brightnessSheet(index, locked=false) {
  const {ctx,requests}=context();
  if(index>=0) ctx.S.outs[index].briLock=locked;
  const elements={};
  ctx.$=selector=>elements[selector]||(elements[selector]={value:'',checked:false,style:{},textContent:'',disabled:false});
  ctx.pad2=value=>String(value).padStart(2,'0');
  ctx.closeSheet=()=>{ctx.closed=true};ctx.renderHome=ctx.renderOuts=ctx.flashSaved=()=>{};
  ctx.sheet=(title,html,mount)=>{
    ctx.markup=html;
    ctx.$('#outputLocked').checked=locked;
    ctx.$('#outputPercent').value='100';
    mount();
  };
  vm.runInContext(html.slice(html.indexOf('function sheetOutputBrightness('),html.indexOf('function pad2(')),ctx);
  ctx.sheetOutputBrightness(index);
  return {ctx,requests,elements};
}
test('locked edits require a freshly entered hardware PIN',async()=>{
  const {ctx,requests}=brightnessSheet(7,true);
  ctx.$('#outputSave').onclick();
  assert.equal(requests.length,0);
  assert.match(ctx.$('#outputError').textContent,/hardware PIN/);
  ctx.$('#outputPin').value='9876';
  ctx.$('#outputPercent').value='0';ctx.$('#outputPercent').oninput();
  ctx.$('#outputSave').onclick();
  await new Promise(setImmediate);
  assert.equal(requests[0].body.hw.led.outputBri[0].bri,0);
  assert.equal(requests[0].body.pin,'9876');
  assert.equal(ctx.closed,true);
});
test('percent controls map 0, 50, and 100 to 0, 128, and 255',async()=>{
  for(const [percent,expected] of [[0,0],[50,128],[100,255]]){
    const {ctx,requests}=brightnessSheet(0);
    ctx.$('#outputPercent').value=String(percent);ctx.$('#outputPercent').oninput();
    ctx.$('#outputSave').onclick();await new Promise(setImmediate);
    assert.equal(requests[0].body.hw.led.outputBri[0].bri,expected);
  }
});
test('lock all requests capture each output independently',async()=>{
  const {ctx,requests}=brightnessSheet(-1);
  ctx.$('#outputPin').value='9876';ctx.$('#outputSave').onclick();
  await new Promise(setImmediate);
  const entries=requests[0].body.hw.led.outputBri;
  assert.equal(entries.length,8);
  entries.forEach((entry,index)=>{
    assert.equal(entry.id,index);assert.equal(entry.lock,true);
    assert.equal(Object.hasOwn(entry,'bri'),false);
  });
});
test('failed password validation keeps the sheet open and reports the failure',async()=>{
  const {ctx}=brightnessSheet(0,true);
  ctx.req=async()=>{throw new Error('denied')};
  ctx.$('#outputPin').value='0000';ctx.$('#outputSave').onclick();
  await new Promise(setImmediate);
  assert.equal(ctx.closed,undefined);
  assert.equal(ctx.$('#outputSave').disabled,false);
  assert.match(ctx.$('#outputError').textContent,/hardware PIN/);
});
